// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint _val, uint _lockTime, uint _putValue, uint _collectAm) public {
        // Setup: initialize MinSum and lock time
        vm.assume(_val > 0);
        vm.assume(_lockTime > 0 && _lockTime < 1000000);
        vm.assume(_putValue > 0 && _putValue < 1e18);
        vm.assume(_collectAm > 0 && _collectAm <= _putValue);

        // Initialize contract with a specific MinSum
        c.SetMinSum(_val);
        c.SetLogFile(address(0));
        c.Initialized();
        uint256 originalMinSum = c.MinSum();

        // Put funds and lock time
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // Collect
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAm));

        // Assert: MinSum never changes
        assertTrue(c.MinSum() == originalMinSum);
    }
}

