pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 am, uint256 lockTime, uint256 deposit) public {
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        am = bound(am, 0, 1e18);
        lockTime = bound(lockTime, 0, 365 days);
        deposit = bound(deposit, 0, 1e18);

        // Setup: set MinSum and log, initialize
        c.SetMinSum(minSum);
        c.Initialized();

        // Give some balance to the contract and put funds
        vm.deal(address(c), 10 ether);
        vm.deal(address(this), deposit);
        vm.prank(address(this));
        c.Put{value: deposit}(lockTime);

        // Now call Collect, which may revert or succeed
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        // Rule: MinSum stays equal to what was set (minSum) regardless of revert or success
        assertTrue(c.MinSum() == minSum);
    }
}

