pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 putAmount, uint256 collectAmount, address sender) public {
        // Ensure addresses are non-zero to avoid issues
        vm.assume(sender != address(0));

        // Initialize the contract (lock SetMinSum)
        c.Initialized();

        // Record MinSum before any Put/Collect
        uint256 minSumBefore = c.MinSum();

        // Fund the sender
        vm.deal(sender, putAmount);
        vm.prank(sender);
        // Call Put to increase balance
        (bool putSuccess, ) = address(c).call{value: putAmount}(abi.encodeWithSignature("Put(uint256)", lockTime));
        if (!putSuccess) {
            // If Put reverts (e.g., overflow), we cannot proceed; assume valid inputs
            vm.assume(false);
        }

        // Now call Collect
        vm.prank(sender);
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // Collect may revert; we only care about MinSum after call

        // Check MinSum unchanged
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumBefore == minSumAfter, "MinSum changed after Collect");
    }
}

