pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _putAmount, uint256 _minSum, uint256 _collectAmount) public {
        // Bound inputs to reasonable ranges
        _lockTime = bound(_lockTime, 0, 1000000);
        _putAmount = bound(_putAmount, 0, 1e26);
        _minSum = bound(_minSum, 0, 1e26);
        _collectAmount = bound(_collectAmount, 0, _putAmount);

        // Prepare: set MinSum and initialize contract
        vm.assume(_minSum <= 1e26);
        c.SetMinSum(_minSum);
        c.Initialized();

        // Fund caller and call Put
        address caller = address(0x1234);
        vm.deal(caller, _putAmount);
        vm.prank(caller);
        c.Put{value: _putAmount}(_lockTime);

        // Record state before Collect
        uint256 callerBalanceBefore = address(caller).balance;
        uint256 contractBalanceBefore = address(c).balance;
        (uint256 unlockTimeBefore, uint256 accBalanceBefore) = c.Acc(caller);

        // Advance time to allow collect
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _collectAmount));

        // General rule: After Collect, acc.balance plus caller's balance should equal previous acc.balance plus caller's balance minus collected amount? 
        // Simpler: the total balance of caller (in contract + external) should be unchanged by Collect except for the withdrawal
        // But easier: check that acc.balance is non-negative and caller's external balance increases by at most _collectAmount

        // Actually we assert a clean invariant: 
        // After Collect, either it reverted (success false) or the caller's balance in contract decreased by exactly _collectAmount and caller's ETH increased by _collectAmount
        if (success) {
            (uint256 unlockTimeAfter, uint256 accBalanceAfter) = c.Acc(caller);
            assertTrue(accBalanceAfter + address(caller).balance == accBalanceBefore + callerBalanceBefore);
        } else {
            (uint256 unlockTimeAfter, uint256 accBalanceAfter) = c.Acc(caller);
            assertTrue(accBalanceAfter == accBalanceBefore);
        }
    }
}

