        c.Initialized();
    }

    // Helper to compute total balance in contract: sum of all Acc balances + contract balance
    // Since we can't iterate over all addresses, we use a known participant.
    // For a general property, we use a single user and track before/after.

    function testFuzz_property(uint256 deposit, uint256 lockTime, uint256 collectAmt) public {
