        c.Put{value: deposit}(lockTime);

        // Warp to after lock time to allow collect
        vm.warp(block.timestamp + lockTime + 1);

        // Get state before collect
        (uint unlockBefore, uint balanceBefore) = c.Acc(alice);
        uint contractBalanceBefore = address(c).balance;
        uint totalBefore = balanceBefore + contractBalanceBefore;

        // Try collect (may revert if balance insufficient)
        bool reverted = false;
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
