contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 minSum, uint256 lockTime, uint256 putValue, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(lockTime <= 1000000);
        vm.assume(putValue <= 100 ether);
        vm.assume(collectAmount <= 100 ether);
        vm.assume(minSum <= 100 ether);

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund sender and contract
        vm.deal(sender, putValue + 1 ether);
        vm.deal(address(c), 10 ether);

        // Record initial contract balance
        uint256 initialBalance = address(c).balance;

        // Put some ether into the contract as sender
        vm.prank(sender);
        c.Put{value: putValue}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Attempt Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: the contract's balance should never increase as a result of Collect
        // (in reference, Collect only decreases or keeps balance; in mutant, if acc.balance == _am, it doesn't execute and balance stays same)
        // We check that contract balance didn't go up (which would be impossible in reference)
        // But actually, since mutant fails to send when balance == _am, balance stays same.
        // Better: after Collect, if it succeeded, contract balance decreased by exactly _am.
        // We'll check: if Collect succeeded, contract balance decreased by _am; 
        // if it failed, balance unchanged.
        uint256 finalBalance = address(c).balance;

        if (success) {
            // Must have decreased by exactly _am
            assertTrue(finalBalance == initialBalance - collectAmount, "Contract balance should decrease by collectAmount on success");
        } else {
            // Must have kept same balance
            assertTrue(finalBalance == initialBalance, "Contract balance should stay same on failure");
        }
    }
}

