        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // Record balance after
        uint256 balanceAfter = c.Acc(caller).balance;

        // General rule: if balanceBefore == minSum, Collect should NOT reduce balance (because reference requires >= but bug requires >)
        // In reference C, Collect succeeds when balanceBefore >= minSum, so balance can decrease.
        // In buggy M, Collect only succeeds when balanceBefore > minSum, so when equal it fails (revert false) and balance unchanged.
        // We assert that when balanceBefore == minSum, the balance did NOT change (i.e., Collect did not succeed)
        // But test must PASS on reference, so we need rule that REFERENCE satisfies always.
        // Reference: Collect can succeed even when balanceBefore == minSum, then balance can decrease.
        // So invariant "balance never decreases when balance == minSum" fails on reference.
        // Incorrect approach. Let's think differently.
        // The difference is: reference allows Collect when balance == minSum; buggy does not.
        // So a rule that holds on reference but fails on buggy: "When balance == minSum, Collect can succeed (i.e., revert false and balance decreases)".
        // But we need a general assertion that passes on reference for all inputs.
        // That assertion is: if balanceBefore == minSum and success == true, then balanceAfter < balanceBefore.
        // Reference: yes, when success true (which is allowed when equal), balance decreases.
        // Buggy: when balanceBefore == minSum, Collect will always revert (success false), so implication trivially holds (antecedent false).
        // So we need an assertion that references passes but buggy fails.
        // Instead, assert: For all inputs where Collect would succeed on reference (including equal case), the balance decreases.
        // But that passes on buggy because it never succeeds on equal.
        // Need a rule that is always true on reference but sometimes false on buggy.
        // Consider: "If balanceBefore >= minSum and am <= balanceBefore and time > unlockTime, then Collect does not revert". This is true on reference (succeeds), false on buggy when balance == minSum.
        // Let's use try/catch to detect revert.

        // Actually simpler: call with try and test if it reverts when conditions meet.
        // But we need a general formula.
        // Final attempt: The property "Collect(uint256) never reduces balance by more than am" holds on reference and might break on buggy? No.
        // Another: "If Collect succeeds, the caller's balance after is balanceBefore - am". True on reference when condition met; on buggy, condition is stricter so it's still true when succeeds.
        // Wait, the break is that buggy prevents Collect when balance == minSum, so when balanceBefore == minSum, Collect won't succeed.
        // So the assertion "If balanceBefore == minSum and am == minSum and time > unlockTime, then Collect can succeed and balance decreases" is false on buggy.
        // For a parameterized test, we can assert: For all inputs with balanceBefore == minSum, Collect does NOT revert (i.e., the call returns true).
        // Reference: yes, because condition is >=, so when equal it passes.
        // Buggy: no, because condition is >, so it reverts when equal.
        // So assertTrue(success) when those conditions hold.

        // Conditions for Collect to be allowed in reference:
        require(balanceBefore >= minSum && am <= balanceBefore && block.timestamp > c.Acc(caller).unlockTime);
        // Actually we already warped, so time condition holds.
        // And we want to test the boundary case balanceBefore == minSum:
        vm.assume(balanceBefore == minSum);

        // Now in reference C, Collect should succeed (success == true)
        assertTrue(success, "Collect should succeed when balance == minSum");
        // This passes on reference (where >= means success) and fails on buggy (where > means revert)
    }
